  const firstSupply=g.deliveries.find(d=>!d.done&&d.id!==g.carry&&Math.hypot(d.x-130,d.y-385)<2);for(const d of g.deliveries){let gr=this.props[d.id];if(!gr){gr=new THREE.Group();const color=new THREE.Color(d.color);this.box(.38,.3,.32,color,0,.18,0,gr);this.box(.4,.04,.34,C.cream,0,.35,0,gr);const lb=this.label(d.label,'#183447',d.color,.8,.2);lb.position.y=.64;gr.add(lb);gr.userData.label=lb;this.props[d.id]=gr;this.scene.add(gr);}gr.visible=!d.done&&(Math.hypot(d.x-130,d.y-385)>=2||d.id===firstSupply?.id||g.carry===d.id);gr.userData.label.visible=g.carry!==d.id;gr.position.copy(pos(d.x,d.y));if(g.carry===d.id){gr.position.y=.82;gr.position.z+=.25;gr.rotation.y=t*.2;}else{gr.position.y=.03;gr.rotation.y=0;}}
  if(!this.smallCarry){this.smallCarry=new THREE.Group();this.box(.3,.2,.22,0xe3c27c,0,.1,0,this.smallCarry);this.scene.add(this.smallCarry);}this.smallCarry.visible=['bait','packet'].includes(g.carry);this.smallCarry.position.copy(pos(g.player.x,g.player.y));this.smallCarry.position.y=.9;this.smallCarry.position.z+=.25;
