  const near=nearest(g);for(const s of stations){const gr=this.stationObjects[s.id],isNear=near?.id===s.id;gr.userData.pad.material.color.setHex(isNear?0x65f0ca:0xd5b465);gr.userData.pad.material.opacity=isNear?.95:.35;const delivered=g.deliveries.find(d=>d.done&&d.target.id===s.id);if(['west','east','camera'].includes(s.id)&&gr.userData.complete!==!!delivered){gr.userData.complete=!!delivered;gr.traverse(m=>{if(m.isMesh&&m!==gr.userData.pad){m.material.transparent=!delivered;m.material.opacity=delivered?1:.19;}});}let txt=(delivered?'✓ ':'')+s.short,color='#fff1d3',bg=isNear?'#1b6b66':'#1b324c';if(s.id==='podium'){txt=g.micOn?'MIC ON':'MIC OFF';bg=g.trump.phase==='talking'?'#b23c30':g.micOn?'#a94336':'#41556b';}if(s.id==='applause'&&g.cooldown>0)txt=`APPLAUSE · ${Math.ceil(g.cooldown)}s`;if(s.id==='ribbon'&&g.ribbonCooldown>0)txt=`RIBBON · ${Math.ceil(g.ribbonCooldown)}s`;if(s.id==='broadcast'){txt=g.show.phase==='live'?'● ON AIR':'GO LIVE';bg=g.show.phase==='live'?'#b23c30':'#1b324c';}if(s.id==='sign'&&g.vance.phase==='active'){txt='DIRECTIONS CHANGED!';bg='#aa6b28';}const threatened=g.warning?.id===s.id&&g.warning.kind==='tamper';if(threatened){gr.userData.pad.material.color.setHex(0xf64b35);gr.userData.pad.material.opacity=.65+Math.sin(t*12)*.3;txt=g.trump.phase==='tampering'?`BOSS: ${Math.ceil(g.trump.timer)}s !`:'BOSS HEADING HERE !';bg='#b33f30';}if(!gr.userData.timer){const bar=this.box(.9,.055,.015,0xf9563c,0,.38,.62,gr);bar.castShadow=false;gr.userData.timer=bar;}gr.userData.timer.visible=threatened&&g.trump.phase==='tampering';gr.userData.timer.scale.x=Math.max(.02,(g.trump.timer||0)/4);this.setLabel(gr.userData.label,txt,color,bg);}
